{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "intro_text",
        "steps_h2",
        "steps_intro_text",
        "step1_card",
        "step2_card",
        "step3_card",
        "step4_card",
        "step5_card",
        "step6_card",
        "step7_card",
        "step8_card",
        "agencies_h2",
        "agency_sos_card",
        "agency_irs_card",
        "agency_ftb_card",
        "agency_dca_card",
        "agency_local_card",
        "quick_actions_h2",
        "quick_actions_stack",
        "sources_h2",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "California LLC Registration Essentials",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Forming a Limited Liability Company (LLC) in California involves several key steps, primarily dealing with the California Secretary of State and the Franchise Tax Board. This guide outlines the general process, typical documents, and involved agencies to help you establish your business entity."
      },
      "children": []
    },
    "steps_h2": {
      "type": "Text",
      "props": {
        "text": "Steps to Form a California LLC",
        "variant": "h2"
      },
      "children": []
    },
    "steps_intro_text": {
      "type": "Text",
      "props": {
        "text": "Here are the general steps to register a small business as an LLC in California:"
      },
      "children": []
    },
    "step1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step1_title_stack",
        "step1_action_text",
        "step1_agency_text",
        "step1_document_text",
        "step1_resource_button"
      ]
    },
    "step1_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "step1_icon",
        "step1_h3"
      ]
    },
    "step1_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000241_01_8_signpost-split.svg"
      },
      "children": []
    },
    "step1_h3": {
      "type": "Text",
      "props": {
        "text": "Step 1: Choose and Reserve Your LLC Name",
        "variant": "h3"
      },
      "children": []
    },
    "step1_action_text": {
      "type": "Text",
      "props": {
        "text": "Action: Select a unique name for your LLC that complies with California naming requirements (must include \"LLC\" or \"Limited Liability Company\"). Check for availability."
      },
      "children": []
    },
    "step1_agency_text": {
      "type": "Text",
      "props": {
        "text": "Agency: California Secretary of State (SOS)."
      },
      "children": []
    },
    "step1_document_text": {
      "type": "Text",
      "props": {
        "text": "Document: Name Availability Search (online or by mail). Optional: Name Reservation Request (Form LLC-1, valid for 60 days)."
      },
      "children": []
    },
    "step1_resource_button": {
      "type": "Button",
      "props": {
        "label": "California SOS Business Search"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://bizfileonline.sos.ca.gov/search/business"
          }
        }
      },
      "children": []
    },
    "step2_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step2_title_stack",
        "step2_action_text",
        "step2_requirement_text"
      ]
    },
    "step2_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "step2_icon",
        "step2_h3"
      ]
    },
    "step2_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000255_01_2_person-badge.svg"
      },
      "children": []
    },
    "step2_h3": {
      "type": "Text",
      "props": {
        "text": "Step 2: Appoint a Registered Agent",
        "variant": "h3"
      },
      "children": []
    },
    "step2_action_text": {
      "type": "Text",
      "props": {
        "text": "Action: Designate a Registered Agent who has a physical street address in California and is available during business hours to accept legal documents on behalf of your LLC. This can be an individual or a registered corporate agent."
      },
      "children": []
    },
    "step2_requirement_text": {
      "type": "Text",
      "props": {
        "text": "Requirement: The agent's address must be a physical address, not a P.O. Box."
      },
      "children": []
    },
    "step3_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step3_title_stack",
        "step3_action_text",
        "step3_agency_text",
        "step3_document_text",
        "step3_key_info_text"
      ]
    },
    "step3_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "step3_icon",
        "step3_h3"
      ]
    },
    "step3_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000255_01_3_file-earmark-text.svg"
      },
      "children": []
    },
    "step3_h3": {
      "type": "Text",
      "props": {
        "text": "Step 3: File Articles of Organization (Form LLC-1)",
        "variant": "h3"
      },
      "children": []
    },
    "step3_action_text": {
      "type": "Text",
      "props": {
        "text": "Action: Prepare and file the Articles of Organization with the California Secretary of State. This officially creates your LLC."
      },
      "children": []
    },
    "step3_agency_text": {
      "type": "Text",
      "props": {
        "text": "Agency: California Secretary of State."
      },
      "children": []
    },
    "step3_document_text": {
      "type": "Text",
      "props": {
        "text": "Document: Articles of Organization (Form LLC-1)."
      },
      "children": []
    },
    "step3_key_info_text": {
      "type": "Text",
      "props": {
        "text": "Key Information: LLC name, registered agent's name and address, LLC's mailing address."
      },
      "children": []
    },
    "step4_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step4_title_stack",
        "step4_action_text",
        "step4_requirement_text",
        "step4_purpose_text"
      ]
    },
    "step4_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "step4_icon",
        "step4_h3"
      ]
    },
    "step4_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000255_01_4_journal-text.svg"
      },
      "children": []
    },
    "step4_h3": {
      "type": "Text",
      "props": {
        "text": "Step 4: Draft an Operating Agreement",
        "variant": "h3"
      },
      "children": []
    },
    "step4_action_text": {
      "type": "Text",
      "props": {
        "text": "Action: Create an Operating Agreement, which is a crucial internal document outlining the ownership structure, member duties, voting rights, and how the LLC will be managed and operated."
      },
      "children": []
    },
    "step4_requirement_text": {
      "type": "Text",
      "props": {
        "text": "Requirement: While not filed with the state, a written Operating Agreement is legally required for California LLCs."
      },
      "children": []
    },
    "step4_purpose_text": {
      "type": "Text",
      "props": {
        "text": "Purpose: Protects limited liability status, prevents disputes, and defines financial and management arrangements."
      },
      "children": []
    },
    "step5_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step5_title_stack",
        "step5_action_text",
        "step5_agency_text",
        "step5_resource_button"
      ]
    },
    "step5_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "step5_icon",
        "step5_h3"
      ]
    },
    "step5_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000255_01_5_hash.svg"
      },
      "children": []
    },
    "step5_h3": {
      "type": "Text",
      "props": {
        "text": "Step 5: Obtain an Employer Identification Number (EIN)",
        "variant": "h3"
      },
      "children": []
    },
    "step5_action_text": {
      "type": "Text",
      "props": {
        "text": "Action: Apply for an EIN from the IRS. This nine-digit number is like a social security number for your business and is required for most LLCs, especially those with employees or multiple members."
      },
      "children": []
    },
    "step5_agency_text": {
      "type": "Text",
      "props": {
        "text": "Agency: Internal Revenue Service (IRS)."
      },
      "children": []
    },
    "step5_resource_button": {
      "type": "Button",
      "props": {
        "label": "IRS EIN Assistant"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.irs.gov/businesses/small-businesses-self-employed/employer-id-numbers"
          }
        }
      },
      "children": []
    },
    "step6_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step6_title_stack",
        "step6_action_text",
        "step6_agency_text",
        "step6_document_text",
        "step6_frequency_text"
      ]
    },
    "step6_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "step6_icon",
        "step6_h3"
      ]
    },
    "step6_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000252_01_2_info-circle.svg"
      },
      "children": []
    },
    "step6_h3": {
      "type": "Text",
      "props": {
        "text": "Step 6: File Initial Statement of Information (Form LLC-12)",
        "variant": "h3"
      },
      "children": []
    },
    "step6_action_text": {
      "type": "Text",
      "props": {
        "text": "Action: Within 90 days of filing your Articles of Organization, you must file an Initial Statement of Information. This provides updated information about your LLC's members, managers, and registered agent."
      },
      "children": []
    },
    "step6_agency_text": {
      "type": "Text",
      "props": {
        "text": "Agency: California Secretary of State."
      },
      "children": []
    },
    "step6_document_text": {
      "type": "Text",
      "props": {
        "text": "Document: Statement of Information (Form LLC-12)."
      },
      "children": []
    },
    "step6_frequency_text": {
      "type": "Text",
      "props": {
        "text": "Frequency: Must be filed biennially (every two years) thereafter."
      },
      "children": []
    },
    "step7_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step7_title_stack",
        "step7_action_text",
        "step7_agency_text",
        "step7_requirement_text"
      ]
    },
    "step7_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "step7_icon",
        "step7_h3"
      ]
    },
    "step7_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000255_01_7_cash-coin.svg"
      },
      "children": []
    },
    "step7_h3": {
      "type": "Text",
      "props": {
        "text": "Step 7: Comply with California Tax Requirements",
        "variant": "h3"
      },
      "children": []
    },
    "step7_action_text": {
      "type": "Text",
      "props": {
        "text": "Action: Register with the California Franchise Tax Board (FTB) and understand your tax obligations. All California LLCs are subject to an annual minimum franchise tax."
      },
      "children": []
    },
    "step7_agency_text": {
      "type": "Text",
      "props": {
        "text": "Agency: California Franchise Tax Board (FTB)."
      },
      "children": []
    },
    "step7_requirement_text": {
      "type": "Text",
      "props": {
        "text": "Requirement: Annual minimum franchise tax (currently $800, subject to change) and potential gross receipts fees."
      },
      "children": []
    },
    "step8_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step8_title_stack",
        "step8_action_text",
        "step8_agencies_text"
      ]
    },
    "step8_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "step8_icon",
        "step8_h3"
      ]
    },
    "step8_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000255_01_8_award.svg"
      },
      "children": []
    },
    "step8_h3": {
      "type": "Text",
      "props": {
        "text": "Step 8: Obtain Business Licenses and Permits",
        "variant": "h3"
      },
      "children": []
    },
    "step8_action_text": {
      "type": "Text",
      "props": {
        "text": "Action: Depending on your business type and location, you may need various federal, state, and local licenses and permits."
      },
      "children": []
    },
    "step8_agencies_text": {
      "type": "Text",
      "props": {
        "text": "Agencies: Federal agencies (e.g., SBA, specific industry regulators), California state agencies (e.g., Department of Consumer Affairs, professional licensing boards), City/County Clerk's office."
      },
      "children": []
    },
    "agencies_h2": {
      "type": "Text",
      "props": {
        "text": "Key Agencies and Resources",
        "variant": "h2"
      },
      "children": []
    },
    "agency_sos_card": {
      "type": "Card",
      "props": {},
      "children": [
        "agency_sos_name",
        "agency_sos_desc"
      ]
    },
    "agency_sos_name": {
      "type": "Text",
      "props": {
        "text": "California Secretary of State (SOS):",
        "variant": "h3"
      },
      "children": []
    },
    "agency_sos_desc": {
      "type": "Text",
      "props": {
        "text": "Handles business entity formation, name registration, and compliance filings (Articles of Organization, Statement of Information)."
      },
      "children": []
    },
    "agency_irs_card": {
      "type": "Card",
      "props": {},
      "children": [
        "agency_irs_name",
        "agency_irs_desc"
      ]
    },
    "agency_irs_name": {
      "type": "Text",
      "props": {
        "text": "Internal Revenue Service (IRS):",
        "variant": "h3"
      },
      "children": []
    },
    "agency_irs_desc": {
      "type": "Text",
      "props": {
        "text": "Issues Employer Identification Numbers (EINs) for federal tax purposes."
      },
      "children": []
    },
    "agency_ftb_card": {
      "type": "Card",
      "props": {},
      "children": [
        "agency_ftb_name",
        "agency_ftb_desc"
      ]
    },
    "agency_ftb_name": {
      "type": "Text",
      "props": {
        "text": "California Franchise Tax Board (FTB):",
        "variant": "h3"
      },
      "children": []
    },
    "agency_ftb_desc": {
      "type": "Text",
      "props": {
        "text": "Manages state income taxes and the annual LLC franchise tax."
      },
      "children": []
    },
    "agency_dca_card": {
      "type": "Card",
      "props": {},
      "children": [
        "agency_dca_name",
        "agency_dca_desc"
      ]
    },
    "agency_dca_name": {
      "type": "Text",
      "props": {
        "text": "California Department of Consumer Affairs:",
        "variant": "h3"
      },
      "children": []
    },
    "agency_dca_desc": {
      "type": "Text",
      "props": {
        "text": "Oversees various professional and occupational licenses."
      },
      "children": []
    },
    "agency_local_card": {
      "type": "Card",
      "props": {},
      "children": [
        "agency_local_name",
        "agency_local_desc"
      ]
    },
    "agency_local_name": {
      "type": "Text",
      "props": {
        "text": "Local City/County Clerk's Office:",
        "variant": "h3"
      },
      "children": []
    },
    "agency_local_desc": {
      "type": "Text",
      "props": {
        "text": "Provides information on local business licenses and permits."
      },
      "children": []
    },
    "quick_actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_llc1",
        "button_ein",
        "button_ftb"
      ]
    },
    "button_llc1": {
      "type": "Button",
      "props": {
        "label": "CA SOS Forms"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.sos.ca.gov/business-programs/business-entities/forms#llc"
          }
        }
      },
      "children": []
    },
    "button_ein": {
      "type": "Button",
      "props": {
        "label": "Get EIN Online"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.irs.gov/businesses/small-businesses-self-employed/apply-for-an-employer-identification-number-ein-online"
          }
        }
      },
      "children": []
    },
    "button_ftb": {
      "type": "Button",
      "props": {
        "label": "CA FTB Business"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ftb.ca.gov/file/business/index.html"
          }
        }
      },
      "children": []
    },
    "sources_h2": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "source_sos",
        "source_irs",
        "source_ftb"
      ]
    },
    "source_sos": {
      "type": "Text",
      "props": {
        "text": "California Secretary of State - Business Programs"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.sos.ca.gov/business-programs/business-entities"
          }
        }
      },
      "children": []
    },
    "source_irs": {
      "type": "Text",
      "props": {
        "text": "Internal Revenue Service - Employer ID Numbers"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.irs.gov/businesses/small-businesses-self-employed/employer-id-numbers"
          }
        }
      },
      "children": []
    },
    "source_ftb": {
      "type": "Text",
      "props": {
        "text": "California Franchise Tax Board - Business"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ftb.ca.gov/file/business/index.html"
          }
        }
      },
      "children": []
    }
  }
}
